        if (off == 0x32af4) { extern uint32_t F_32af4(uint32_t,uint32_t,uint32_t,uint32_t,uint32_t,uint32_t,uint32_t,uint32_t,uint32_t,uint32_t,uint32_t,uint32_t,uint32_t); return F_32af4(r0,r1,r2,r3,r4,r5,r6,r7,r8,r9,r10,r11,sp); }
        if (off == 0x7659c) { extern uint32_t F_7659c(uint32_t,uint32_t,uint32_t,uint32_t,uint32_t,uint32_t,uint32_t,uint32_t,uint32_t,uint32_t,uint32_t,uint32_t,uint32_t); return F_7659c(r0,r1,r2,r3,r4,r5,r6,r7,r8,r9,r10,r11,sp); }
        if (off == 0x2afa4) { extern uint32_t F_2afa4(uint32_t,uint32_t,uint32_t,uint32_t,uint32_t,uint32_t,uint32_t,uint32_t,uint32_t,uint32_t,uint32_t,uint32_t,uint32_t); return F_2afa4(r0,r1,r2,r3,r4,r5,r6,r7,r8,r9,r10,r11,sp); }
